(2, 'logo_big', 'assets/images/configs/Web AÌnh TieÌu ÄeÌÌ mtinh (2000 x 1000 px).PNG', '0000-00-00 00:00:00', '2025-09-01 12:11:17', 'image', NULL),
(3, 'logo_big_mobile', 'assets/images/configs/Web AÌnh TieÌu ÄeÌÌ dhoai (1000 x 1000 px).png.PNG', '2025-03-16 16:19:47', '2025-09-05 11:21:46', 'image', NULL),
(5, 'textDecription', 'Chúng tôi thích thiết kế phòng học cho các lớp học nhỏ và cho thuê lại. Một dịch vụ ưu ái cho các bạn giáo viên, người training, và các bạn sinh viên với công việc dạy thêm tay trái. Bất cứ thứ gì hiệu dụng và thú vị đều có thể đáp ứng được. Tuy nhiên, chúng tôi hiểu rằng việc chi hàng chục triệu cho một căn phòng tùy chỉnh có thể sẽ không phù hợp với ngân sách của bạn. Chúng tôi có thể giảm giá cho những ai sẵn sàng dấn thân vào đam mê giảng dạy, truyền lửa nhiệt huyết. Bạn cung cấp cho chúng tôi thông tin (bộ môn, lịch giảng dạy, số điện thoại liên hệ, v.v.) và chúng tôi sẽ gợi ý cho bạn một phòng học đẹp mắt, tùy chỉnh. Một phòng học tốt sẽ giúp đưa lớp bạn đi lên. Hãy liên hệ để tìm hiểu thêm.', '0000-00-00 00:00:00', '2025-07-22 10:40:40', 'text', NULL),
