INSERT INTO `products` (`id`, `name`, `content`, `image`, `status`, `createdAt`, `updatedAt`, `equipment`, `contains`, `description`, `price`, `capacity`, `isSpecial`) VALUES
(2, 'PHÒNG HỌC 12 CHỖ', '<h2>PHÒNG DẠY HỌC CHO THUÊ BÉ BÉ XINH XINH CÓ KHÔNG GIAN THOÁNG TẠI ĐÀ NẴNG</h2><p><br></p><p>VỊ TRÍ TRUNG TÂM THÀNH PHỐ</p><p>Nằm song song với tại trục đường đừng Nguyễn Văn Linh, khu vực trung tâm thành phố dễ dàng di chuyển về từ nhiều hướng.</p>', 'assets/images/products/Web phoÌng mtinh.png.PNG', 1, '2025-01-08 15:48:44', '2025-09-08 07:02:43', 'Tivi - Điều Hòa - Bảng trắng bút lông - Bàn ghế - Kệ sách', '12 chỗ ngồi', 'Phòng có cửa sổ nhìn ra ban công', '80.000 đ/h (đã bao gồm bãi xe, wifi, nước uống)', 0, 0),
(4, 'PHÒNG HỌC 16 CHỖ', '<p>Quá rộng rãi, thoáng mát</p>', 'assets/images/products/Web phÃ²ng mtinh.png', 1, '2025-01-08 15:50:10', '2025-09-08 04:49:41', 'Máy chiếu, Bảng, Bàn ghế ...', '16 chỗ', 'Quá rộng rãi, thoáng mát', '80.000 đ/h (đã bao gồm bãi xe, wifi, nước uống)', 0, 1),
(5, 'PHÒNG HỌC 22 CHỖ', '<p><strong style=\"color: rgb(0, 0, 0);\">Quá rộng rãi, thoáng mát</strong></p>', 'assets/images/products/Web phoÌng mtinh 3.png.PNG', 1, '2025-01-08 15:50:28', '2025-09-08 07:03:05', 'Tai nghe, Máy tính, Bàn ghế ...', '22 Chỗ', 'Quá rộng rãi, thoáng mát', '80.000 đ/h (đã bao gồm bãi xe, wifi, nước uống)', 0, 0),
(6, 'PHÒNG HỌC 30 CHỖ', '<p><strong style=\"color: rgb(0, 0, 0);\">Quá rộng rãi, thoáng mát</strong></p>', 'assets/images/products/Web phoÌng mtinh 4.png.PNG', 1, '2025-01-08 15:51:26', '2025-09-08 07:03:20', 'Máy chiếu, bàn ghế ...', '30 Chỗ', 'Quá rộng rãi, thoáng mát', '80.000 đ/h (đã bao gồm bãi xe, wifi, nước uống)', 0, 0),
(12, 'PHÒNG HỌC 35 CHỖ', '<p>Phòng dạy học dành cho lớp đông học viên, họp nhóm số lượng lớn, training, thuyết trình</p>', 'assets/images/products/Web phoÌng mtinh 5.png.PNG', 1, '2025-07-31 07:50:52', '2025-09-08 07:03:47', 'Máy chiếu, điều hòa, bảng trắng', 'Phòng có sức chứa 35 chỗ ngồi', 'Phòng có trang bị máy chiếu độ phân giải cao', '80.000 đ/h (đã bao gồm bãi xe, wifi, nước uống)', 0, 0),
(13, 'PHÒNG HỌC 40 CHỖ', '<p>CHO THUÊ PHÒNG DẠY HỌC SỨC CHỨA LỚN TẠI ĐÀ NẴNG</p>', 'assets/images/products/Web phoÌng mtinh 6.png.PNG', 1, '2025-07-31 07:54:03', '2025-09-08 07:04:08', 'Máy chiếu, điều hòa, bảng trắng, bàn ghế băng dài', '40 chỗ ngồi cho học viên', 'Cho Thuê Phòng Dạy Học lớn tại Đà Nẵng', '80.000 đ/h (đã bao gồm bãi xe, wifi, nước uống)', 0, 0),
(15, 'PHÒNG HỌC 45 CHỖ', '<p>abc</p>', 'assets/images/products/Web phoÌng mtinh 7.png.PNG', 1, '2025-09-02 05:10:14', '2025-09-08 07:04:20', 'Máy chiếu, điều hòa, bảng trắng, bàn ghế, kệ sách', 'Sức chứa 45 chỗ ngồi', 'Phòng dành cho lớp đông học viên', '80.000 đ/h (đã bao gồm bãi xe, wifi, nước uống)', 0, 0);
